/* Server-backed discovery. Only the current page and up to six shortlisted watches are hydrated. */
(function(root){'use strict';
const M=root.AtlasFinderModel,$=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let pendingNotes=[];
let metadata,callbacks={},state=M.read(''),draft,controller,sequence=0,filterTimer,suggestTimer,suggestController,suggestSequence=0,suggestions=[],active=-1;
const defaults=()=>M.read('');
const api=()=>root.ATLAS_CONFIG?.finderApiBase||'';
async function request(route,params,signal){const response=await fetch(api()+'/v1/finder/'+route+(params?'?'+params:''),{signal});let body;try{body=await response.json();}catch{throw new Error('Watch Finder needs its search API. Start the indexed preview or connect the catalog database.');}if(!response.ok)throw new Error(body.error||'Watch search is temporarily unavailable.');return body;}
function configure(value){callbacks=value;metadata=value.metadata;bindGlobal();}
function url(s){return '#finder'+(M.serialize(s).toString()?'?'+M.serialize(s):'');}
function fromLocation(){state=M.read(location.hash.split('?')[1]||'');return state;}
function set(next,{push=true,refresh=true}={}){state=M.read(M.serialize({...defaults(),...next}));history[push?'pushState':'replaceState'](null,'',url(state));if(refresh){syncControls();load();}}
function search(query){const parsed=M.parse(query,metadata?.facets);pendingNotes=parsed.notes;state={...defaults(),...parsed.filters,q:parsed.text};callbacks.navigate?.('finder',state);if(parsed.notes.length)root.AtlasWorkspace.notify?.(parsed.notes.join(' '));}
function label(key,value,s=state){if(M.facets[key])return M.facets[key]+': '+value;if(key==='q')return 'Text: '+value;const [field,bound]=key.split('.');const op={min:'≥',max:'≤',lt:'<',gt:'>'}[bound];const unit={price:s.currency,diameter:'mm',thickness:'mm',lug:'mm',reserve:'h',water:'m',frequency:'Hz',jewels:''}[field];return (M.numeric[field]||key)+' '+op+' '+Number(value).toLocaleString('en-US')+' '+unit;}
function entries(s){return [...Object.keys(M.facets).flatMap(key=>(s[key]||[]).map(value=>({key,value}))),...Object.keys(M.numeric).flatMap(k=>['min','max','lt','gt'].filter(b=>s[k+'.'+b]!=null).map(b=>({key:k+'.'+b,value:s[k+'.'+b]}))),...(s.q?[{key:'q',value:s.q}]:[])];}
function chips(){return entries(state).map(({key,value})=>`<button class="finder-chip" data-remove-filter="${esc(key)}" data-value="${esc(value)}" aria-label="Remove ${esc(label(key,value))}">${esc(label(key,value))}<span aria-hidden="true">×</span></button>`).join('');}
function checkGroup(key,s){const options=metadata?.facets[key]||[];const values=[...options,...(s[key]||[]).filter(value=>!options.some(x=>x.value===value)).map(value=>({value,count:0}))];return values.length?`<div class="finder-options">${values.map(x=>`<label class="finder-check"><input type="checkbox" data-facet="${key}" value="${esc(x.value)}" ${(s[key]||[]).includes(x.value)?'checked':''}><span>${esc(x.value)}</span><small>${x.count.toLocaleString('en-US')}</small></label>`).join('')}</div>`:'<p class="finder-help">No documented values yet.</p>';}
function range(key,s,unit){const lo=s[key+'.min']??s[key+'.gt']??'',hi=s[key+'.max']??s[key+'.lt']??'';return `<div class="finder-range"><label>Minimum${s[key+'.gt']!=null?' (exclusive)':''}<input type="number" min="0" step="any" inputmode="decimal" data-bound="${key}.min" value="${lo}" aria-label="Minimum ${M.numeric[key]}" placeholder="Any ${unit}"></label><span>–</span><label>Maximum${s[key+'.lt']!=null?' (exclusive)':''}<input type="number" min="0" step="any" inputmode="decimal" data-bound="${key}.max" value="${hi}" aria-label="Maximum ${M.numeric[key]}" placeholder="Any ${unit}"></label></div>${key==='diameter'?`<div class="diameter-sliders"><input type="range" min="20" max="60" step="0.5" value="${lo||20}" data-slider="diameter.min" aria-label="Minimum diameter slider"><input type="range" min="20" max="60" step="0.5" value="${hi||60}" data-slider="diameter.max" aria-label="Maximum diameter slider"></div><p class="finder-help">Adjust the range or enter an exact limit.</p>`:''}`;}
function section(title,content,open=false){return `<details class="finder-section" ${open?'open':''}><summary>${title}<span aria-hidden="true">+</span></summary><div class="finder-section-body">${content}</div></details>`;}
function filters(s){return section('Identity',checkGroup('brand',s)+`<details class="finder-subsection"><summary>Collections</summary>${checkGroup('collection',s)}</details>`+checkGroup('kind',s),true)+
 section('Price',`<label class="finder-select">Price source<select data-option="source">${(metadata?.priceSources||[{value:'official_retail',label:'Official retail snapshot'}]).map(x=>`<option value="${x.value}" ${s.source===x.value?'selected':''}>${x.label}</option>`).join('')}</select></label><label class="finder-select">Currency<select data-option="currency">${[...new Set(['USD',...(metadata?.currencies||[])])].map(x=>`<option ${s.currency===x?'selected':''}>${x}</option>`).join('')}</select></label>${range('price',s,s.currency)}<p class="finder-help">Prices retain their captured market and currency. Unknown prices do not satisfy a budget.</p>`,true)+
 section('Dimensions',`<p class="finder-field">Case diameter · mm</p>${range('diameter',s,'mm')}<p class="finder-field">Case thickness · mm</p>${range('thickness',s,'mm')}<details class="finder-subsection"><summary>Lug to lug</summary>${range('lug',s,'mm')}</details>`,true)+
 section('Case',checkGroup('material',s)+`<details class="finder-subsection"><summary>Case shape</summary>${checkGroup('shape',s)}</details>`)+
 section('Movement',checkGroup('movement',s)+`<p class="finder-field">Power reserve · hours</p>${range('reserve',s,'h')}<details class="finder-subsection"><summary>Calibre & advanced details</summary>${checkGroup('caliber',s)}<p class="finder-field">Manufacture / in-house</p>${checkGroup('inhouse',s)}<p class="finder-field">Frequency · Hz</p>${range('frequency',s,'Hz')}<p class="finder-field">Movement jewels</p>${range('jewels',s,'jewels')}</details>`)+
 section('Complications',`<label class="finder-select">Selected complications<select data-option="complicationsMode"><option value="all" ${s.complicationsMode==='all'?'selected':''}>Match all selected</option><option value="any" ${s.complicationsMode==='any'?'selected':''}>Match any selected</option></select></label>${checkGroup('complication',s)}`)+
 section('Water resistance',`<label class="finder-select">Minimum stated rating<select data-water><option value="">Any / unspecified</option>${[0,30,50,100,200,300,1000].map(x=>`<option value="${x}" ${s['water.min']===x?'selected':''}>${x} m+</option>`).join('')}</select></label><p class="finder-help">Unknown ratings remain unknown. 1 bar / ATM = 10 m.</p>`)+
 section('Dial',checkGroup('dial',s))+section('Strap / bracelet',checkGroup('strap',s))+section('Stated style',checkGroup('style',s)+'<p class="finder-help">Only source labels are used. An undocumented dress or sports style is unknown.</p>')+
 section('Production & catalog',`<p class="finder-field">Production</p>${checkGroup('production',s)}<p class="finder-field">Catalog status</p>${checkGroup('status',s)}<p class="finder-help">An official snapshot does not establish current production or stock availability.</p>`);}
function render(){fromLocation();return `<section class="finder-intro"><p class="eyebrow">THE WATCH FINDER</p><div><h1>Find your next perspective.</h1><span class="finder-edition">${metadata?.total?.toLocaleString('en-US')||'—'} REFERENCES / ONE ATLAS</span></div><p>Start with a reference, or describe what matters. Refine the mechanics, proportions and details.</p></section><form class="finder-search" id="finder-search-form"><label class="skip-label" for="finder-query">Search all watch references</label><span aria-hidden="true">⌕</span><input id="finder-query" type="search" value="${esc(state.q)}" placeholder="A reference, a collection, or automatic titanium GMT under 41mm…" autocomplete="off"><button class="button primary">Search</button></form><div class="finder-discovery"><span class="tiny-label">START EXPLORING</span>${['Automatic GMT under $15,000','Titanium watches under 40mm','Chronograph with 70 hour power reserve'].map(q=>`<button data-discover="${esc(q)}">${esc(q)} ↗</button>`).join('')}</div><div class="finder-layout"><aside id="finder-sidebar" class="finder-sidebar" aria-label="Watch filters"><div class="finder-sidebar-title"><h2>Refine the search</h2><button class="text-button" data-clear-finder>Clear</button></div><p class="finder-help">Options show catalog-wide coverage. Selections within a category match any; categories combine together.</p><div id="finder-filter-controls">${filters(state)}</div></aside><section class="finder-results" aria-label="Matching watches"><div class="finder-toolbar"><div><p class="eyebrow">THE SHORTLIST STARTS HERE</p><strong id="finder-count" role="status">Finding references…</strong></div><div><button class="button finder-mobile-toggle" id="open-finder-filters">Filters <span id="finder-filter-number"></span></button><select id="finder-sort" aria-label="Sort matching watches">${Object.entries(M.sorts).map(([value,name])=>`<option value="${value}" ${state.sort===value?'selected':''}>${name}</option>`).join('')}</select><button class="button finder-share" id="share-finder" aria-label="Copy Watch Finder link">Share ↗</button></div></div><div id="finder-active" class="finder-active" aria-label="Active filters">${chips()}</div><div id="finder-notes"></div><div id="finder-results-content" aria-busy="true"><div class="loading">Searching the catalog…</div></div><div class="finder-provenance"><span class="tiny-label">A DATABASE WITH CONTEXT</span><p>Specifications describe the captured source. Missing values stay unknown. Prices retain their original currency; catalog snapshots do not establish availability today.</p></div></section></div><dialog id="finder-filter-dialog" class="finder-filter-dialog" aria-labelledby="mobile-filters-title"><form method="dialog" class="mobile-filter-heading"><div><p class="eyebrow">THE WATCH FINDER</p><h2 id="mobile-filters-title">Refine your search</h2></div><button class="button" aria-label="Close filters">×</button></form><div id="mobile-filter-controls"></div><div class="mobile-filter-footer"><button class="text-button" id="clear-mobile-filters">Clear</button><button class="button primary" id="apply-mobile-filters">Show matching watches</button></div></dialog>`;}
function safe(value){try{const u=new URL(value);return u.protocol==='https:'?u.href:'';}catch{return '';}}
function card(r){const n=r.finder||{},c=n.facets?.complication||[],p=r.finder_price;const price=p?p.currency+' '+Number(p.amount).toLocaleString('en-US'):r.price_value!=null?r.currency+' '+Number(r.price_value).toLocaleString('en-US'):r.price||'Price unavailable';const priceLabel=p?((metadata?.priceSources||[]).find(x=>x.value===p.source)?.label||p.source)+(p.market?' · '+p.market:''):r.price_value!=null?(r.source_kind==='Official catalog'?'Retail snapshot':'Archive price')+(r.market?' · '+r.market:''):'Recorded price unavailable';return `<article class="finder-card"><button class="finder-watch-open" data-finder-record="${esc(r.id)}" aria-label="View ${esc(r.brand+' '+r.reference_number)}"><div class="finder-watch-image"><div class="finder-image-fallback"><span>${esc(r.brand)}</span><small>${esc(r.reference_number)}</small></div>${safe(r.image_url)?`<img src="${esc(safe(r.image_url))}" alt="${esc(r.brand+' '+r.specific_model)}" loading="lazy" referrerpolicy="no-referrer" onload="this.previousElementSibling.hidden=true" onerror="this.remove()">`:''}<span class="finder-status ${r.verification_status==='unverified'?'historical':''}">${esc(n.status||'Archive snapshot')}</span></div><div class="finder-card-body"><p class="eyebrow">${esc(r.brand)}</p><h3>${esc(r.specific_model||r.parent_model||'Watch reference')}</h3><p class="finder-collection">${esc(r.collection_label||r.parent_model||'Collection unspecified')}</p><p class="finder-reference">REF. ${esc(r.reference_number)}</p><div class="finder-card-price">${esc(price)}<small>${esc(priceLabel)}</small></div><dl class="finder-specs"><div><dt>Diameter</dt><dd>${n.diameter!=null?n.diameter+' mm':'Unknown'}</dd></div><div><dt>Movement</dt><dd>${esc(n.facets?.movement?.join(' / ')||'Unknown')}</dd></div><div><dt>Case</dt><dd>${esc(n.facets?.material?.filter(x=>x!=='Gold').join(' / ')||r.case_material||'Unknown')}</dd></div><div><dt>Water rating</dt><dd>${n.water!=null?n.water+' m':'Unknown'}</dd></div></dl><p class="finder-complications">${esc(c.slice(0,3).join(' · ')||'Functions unspecified')}${c.length>3?' +'+(c.length-3):''}</p><p class="finder-production">${esc(n.production||'Production status unknown')}</p></div></button>${root.AtlasWorkspace.selectionButton(r)}</article>`;}
function remove(key,value){const next={...state,page:1};if(Array.isArray(next[key]))next[key]=next[key].filter(x=>x!==value);else delete next[key];set(next);}
function syncControls(){const el=$('#finder-filter-controls');if(el){const open=[...el.querySelectorAll('details')].map(x=>x.open);el.innerHTML=filters(state);[...el.querySelectorAll('details')].forEach((x,i)=>{if(open[i]!=null)x.open=open[i];});bindControls(el,false);}const sort=$('#finder-sort');if(sort)sort.value=state.sort;const q=$('#finder-query');if(q&&document.activeElement!==q)q.value=state.q;}
function bindControls(el,mobile){for(const input of el.querySelectorAll('input,select'))input.addEventListener(['number','range'].includes(input.type)?'input':'change',()=>{
 const next={...(mobile?draft:state),page:1};if(input.dataset.facet){const key=input.dataset.facet;next[key]=[...el.querySelectorAll(`[data-facet="${key}"]:checked`)].map(x=>x.value);}else if(input.dataset.bound||input.dataset.slider){const key=input.dataset.bound||input.dataset.slider;const field=key.split('.')[0];delete next[field+(key.endsWith('.min')?'.gt':'.lt')];if(input.value==='')delete next[key];else next[key]=+input.value;const slider=el.querySelector(`[data-slider="${key}"]`);if(slider&&input.value!=='')slider.value=input.value;if(input.dataset.slider){const corresponding=el.querySelector(`[data-bound="${key}"]`);if(corresponding)corresponding.value=input.value;}}else if(input.dataset.option)next[input.dataset.option]=input.value;else if(input.hasAttribute('data-water')){delete next['water.min'];if(input.value!=='')next['water.min']=+input.value;}
 if(mobile){draft=next;$('#apply-mobile-filters').textContent='Updating result count…';$('#apply-mobile-filters').disabled=true;clearTimeout(filterTimer);filterTimer=setTimeout(previewDraft,160);}else{state=next;history[['number','range'].includes(input.type)?'replaceState':'pushState'](null,'',url(state));clearTimeout(filterTimer);filterTimer=setTimeout(load,160);}
 });}
async function previewDraft(){const token=M.serialize(draft).toString();$('#apply-mobile-filters').textContent='Updating result count…';$('#apply-mobile-filters').disabled=true;try{const r=await request('search',token);if($('#finder-filter-dialog')?.open&&M.serialize(draft).toString()===token){$('#apply-mobile-filters').textContent='Show '+r.total.toLocaleString('en-US')+' watches';$('#apply-mobile-filters').disabled=false;}}catch(e){if($('#finder-filter-dialog')?.open&&M.serialize(draft).toString()===token){$('#apply-mobile-filters').textContent=e.message;$('#apply-mobile-filters').disabled=true;}}}
async function load(){controller?.abort();controller=new AbortController();const ticket=++sequence,results=$('#finder-results-content');if(!results)return;results.setAttribute('aria-busy','true');$('#finder-count').textContent='Finding references…';$('#finder-active').innerHTML=chips();$('#finder-filter-number').textContent=entries(state).length||'';bindChipActions();
 try{const data=await request('search',M.serialize(state),controller.signal);if(ticket!==sequence||!$('#finder-results-content'))return;
  if(data.total&&data.page>data.pages){set({...state,page:data.pages},{push:false});return;}
  state=data.state;history.replaceState(null,'',url(state));root.AtlasWorkspace.upsert(data.watches,{replace:true});$('#finder-active').innerHTML=chips();bindChipActions();$('#finder-count').textContent=data.total.toLocaleString('en-US')+' matching reference'+(data.total===1?'':'s');
  $('#finder-notes').innerHTML=[...new Set([...pendingNotes,...data.interpretation.notes,...(state.complication?.length>1?[state.complicationsMode==='any'?'A watch may match any selected complication.':'Every selected complication is required.']:[])])].map(n=>`<p class="finder-interpretation">${esc(n)}</p>`).join('');
  results.innerHTML=data.watches.length?`<div class="finder-grid">${data.watches.map(card).join('')}</div><div class="pagination"><button class="button" id="finder-prev" ${state.page===1?'disabled':''}>Previous</button><span>${state.page} / ${data.pages}</span><button class="button" id="finder-next" ${state.page===data.pages?'disabled':''}>Next</button></div>`:`<div class="empty finder-empty"><span class="tiny-label">A MORE PRECISE SEARCH</span><h2>No documented matches.</h2><p>The catalog has no watches satisfying every active constraint. Missing specifications cannot establish a match.</p>${data.relaxations.length?`<p class="finder-help">Try removing one requirement:</p><div>${data.relaxations.map(x=>`<button class="button" data-relax="${esc(x.key)}">Remove ${esc(M.facets[x.key]||M.numeric[x.key.split('.')[0]]||x.key)} · ${x.count.toLocaleString('en-US')} matches</button>`).join('')}</div>`:''}<button class="text-button" data-clear-finder>Explore all references</button></div>`;
  results.removeAttribute('aria-busy');$('#finder-prev')?.addEventListener('click',()=>set({...state,page:state.page-1}));$('#finder-next')?.addEventListener('click',()=>{set({...state,page:state.page+1});$('#finder-count').scrollIntoView({block:'start'});});
  results.querySelectorAll('[data-relax]').forEach(b=>b.onclick=()=>{const next={...state,page:1};delete next[b.dataset.relax];set(next);});results.querySelectorAll('[data-finder-record]').forEach(b=>b.onclick=()=>callbacks.openRecord?.(b.dataset.finderRecord));bindClear();root.AtlasWorkspace.bindSelection();
 }catch(e){if(e.name==='AbortError'||ticket!==sequence)return;results.removeAttribute('aria-busy');$('#finder-count').textContent='Search unavailable';results.innerHTML=`<div class="empty"><h2>The catalog could not be searched.</h2><p>${esc(e.message)}</p><button class="button" id="retry-finder">Retry search</button></div>`;$('#retry-finder').onclick=load;}
}
function bindClear(){document.querySelectorAll('[data-clear-finder]').forEach(b=>b.onclick=()=>{pendingNotes=[];set(defaults());});}
function bindChipActions(){$('#finder-active')?.querySelectorAll('[data-remove-filter]').forEach(b=>b.onclick=()=>remove(b.dataset.removeFilter,b.dataset.value));}
async function copyLink(){try{await navigator.clipboard.writeText(location.origin+location.pathname+url(state));$('#share-finder').textContent='Copied ✓';setTimeout(()=>{if($('#share-finder'))$('#share-finder').textContent='Share ↗';},2000);}catch{const input=document.createElement('input');input.value=location.origin+location.pathname+url(state);input.readOnly=true;input.setAttribute('aria-label','Copy this finder URL');$('#finder-active').append(input);input.select();}}
function bind(){fromLocation();bindControls($('#finder-filter-controls'),false);$('#finder-search-form').onsubmit=e=>{e.preventDefault();search($('#finder-query').value);};$('#finder-sort').onchange=e=>set({...state,sort:e.target.value,page:1});$('#share-finder').onclick=copyLink;document.querySelectorAll('[data-discover]').forEach(b=>b.onclick=()=>search(b.dataset.discover));bindClear();
 $('#open-finder-filters').onclick=()=>{draft={...state};$('#mobile-filter-controls').innerHTML=filters(draft);bindControls($('#mobile-filter-controls'),true);$('#finder-filter-dialog').showModal();$('#apply-mobile-filters').disabled=false;previewDraft();};
 $('#apply-mobile-filters').onclick=()=>{$('#finder-filter-dialog').close();set(draft);};$('#clear-mobile-filters').onclick=()=>{draft=defaults();$('#mobile-filter-controls').innerHTML=filters(draft);bindControls($('#mobile-filter-controls'),true);previewDraft();};load();}
function closeSuggestions(cancel=true){if(cancel){clearTimeout(suggestTimer);suggestController?.abort();suggestSequence++;}suggestions=[];active=-1;const popup=$('#universal-suggestions');if(popup)popup.hidden=true;const input=$('#universal-query');if(input){input.setAttribute('aria-expanded','false');input.removeAttribute('aria-activedescendant');}}
function bindGlobal(){const form=$('#universal-search'),input=$('#universal-query'),popup=$('#universal-suggestions');if(!form)return;
 form.onsubmit=e=>{e.preventDefault();const chosen=suggestions[active];closeSuggestions();if(chosen)callbacks.navigate?.('finder',{...defaults(),...chosen.state});else search(input.value);input.blur();};
 input.oninput=()=>{clearTimeout(suggestTimer);suggestController?.abort();const q=input.value.trim(),ticket=++suggestSequence;closeSuggestions(false);if(!q)return;suggestTimer=setTimeout(async()=>{suggestController=new AbortController();try{const data=await request('suggest',new URLSearchParams({q}),suggestController.signal);if(ticket!==suggestSequence||input.value.trim()!==q||document.activeElement!==input)return;let index=0;suggestions=data.groups.flatMap(g=>g.items);popup.innerHTML=data.groups.map(g=>`<div class="suggestion-group"><div class="tiny-label">${g.label}</div>${g.items.map(x=>{const i=index++;return `<button type="button" role="option" aria-selected="false" id="suggestion-${i}" data-suggestion="${i}"><strong>${esc(x.label)}</strong>${x.detail?`<small>${esc(x.detail)}</small>`:''}</button>`;}).join('')}</div>`).join('');popup.hidden=false;input.setAttribute('aria-expanded','true');popup.querySelectorAll('[data-suggestion]').forEach(b=>{b.onpointerdown=e=>e.preventDefault();b.onclick=()=>{const item=suggestions[+b.dataset.suggestion];closeSuggestions();callbacks.navigate?.('finder',{...defaults(),...item.state});input.blur();};});}catch(e){if(e.name!=='AbortError'&&ticket===suggestSequence&&document.activeElement===input){popup.innerHTML='<p class="finder-help">Press Enter to search the catalog.</p>';popup.hidden=false;input.setAttribute('aria-expanded','true');}}},140);};
 input.onkeydown=e=>{if(e.key==='Escape'){closeSuggestions();input.blur();}else if(['ArrowDown','ArrowUp'].includes(e.key)&&suggestions.length){e.preventDefault();active=(active+(e.key==='ArrowDown'?1:-1)+suggestions.length)%suggestions.length;popup.querySelectorAll('[role="option"]').forEach((x,i)=>x.setAttribute('aria-selected',i===active?'true':'false'));input.setAttribute('aria-activedescendant','suggestion-'+active);$('#suggestion-'+active)?.scrollIntoView({block:'nearest'});}};
 document.addEventListener('pointerdown',e=>{if(!form.contains(e.target))closeSuggestions();});input.onfocus=()=>{if(input.value)input.oninput();};
 document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key==='k'){e.preventDefault();input.focus();input.select();}});
}
async function getWatches(ids){if(!ids.length)return [];return (await request('watches',new URLSearchParams({ids:ids.slice(0,6).join(',')}))).watches;}
async function getComparison(value){return request('compare',new URLSearchParams({q:value.query||'',rules:JSON.stringify(value.rules||[]),unknown:value.unknown?'1':'0',limit:Math.min(value.shown||12,96)}));}
root.AtlasFinder={getComparison,configure,render,bind,url,search,getWatches,dispose(){controller?.abort();closeSuggestions();},get state(){return state;}};
})(globalThis);
